// Use the LLM's branch pick only if it is one of the known codes; always flag it for review.
const ctx = JSON.parse(JSON.stringify($('Resolve Location').first().json));
const answer = String($json?.choices?.[0]?.message?.content ?? '').trim().toUpperCase().replace(/[^A-Z]/g, '');
const opt = ctx.location.options?.[answer];
if (opt) {
  Object.assign(ctx.location, { status: 'RESOLVED', code: answer, ...opt, method: 'LLM_FALLBACK', method_detail: `AI fallback (no PO code or Ship To match) = ${answer}; verify`, needs_review: true });
  ctx.warnings.push(`Location ${answer} chosen by LLM fallback; verify`);
} else {
  ctx.location.method = `LLM_FALLBACK answered ${answer || 'nothing'}`;
}
delete ctx.location.options;
delete ctx.location.fallback_prompt;
return [{ json: ctx }];

// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["GLOBAL_CONFIG.extraction_endpoint", "GLOBAL_CONFIG.glm_extraction_model", "GLOBAL_CONFIG.glm_fallback_model", "GLOBAL_CONFIG.glm_header_max_tokens", "GLOBAL_CONFIG.glm_lines_max_tokens", "GLOBAL_CONFIG.glm_fallback_max_tokens", "INV_PROC_CONFIG.validation_tolerance", "INV_PROC_CONFIG.email_body_min_chars", "LOCATION_CONFIG.conflict_policy", "LOCATION_CONFIG.enable_llm_fallback", "ROUTING_CONFIG.advertising_patterns", "ROUTING_CONFIG.utility_patterns"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

const ctx = JSON.parse(
  JSON.stringify($('Loop Invoices').item.json)
);

ctx.warnings = Array.isArray(ctx.warnings)
  ? ctx.warnings
  : [];

const row = $('Insert Tracking Row').item.json;
ctx.tracking_id = row?.id ?? null;

// Duplicate-check results entering this node.
const posted = $input.all()
  .map(item => item.json)
  .filter(r =>
    r?.id != null &&
    String(r.id) !== String(ctx.tracking_id)
  );

if (
  !ctx.route &&
  ctx.invoice?.invoice_number &&
  posted.length > 0
) {
  ctx.route = 'EXCEPTION';
  ctx.status = 'DUPLICATE';
  ctx.reason =
    `Already posted (tracking row ${posted[0].id}, Sage bill ${posted[0].sage_bill_id || 'n/a'})`;
}

return { json: ctx };

// Lane rules (deterministic): credit memo -> exception; PO -> Direct; everything else -> Indirect.
const R = $('Build Config').first().json.cfg.ROUTING_CONFIG;
const toRe = list => (Array.isArray(list) ? list : []).map(p => new RegExp(p, 'i'));
const CONFIG = { ADVERTISING: toRe(R.advertising_patterns), UTILITY: toRe(R.utility_patterns) };
const ctx = $json;
if (ctx.location) { delete ctx.location.options; delete ctx.location.fallback_prompt; }
if (ctx.route) return [{ json: ctx }];

const exc = (status, reason) => { ctx.route = 'EXCEPTION'; ctx.status = status; ctx.reason = reason; return [{ json: ctx }]; };
const loc = ctx.location || {};
const inv = ctx.invoice;

const total = inv.current_charges ?? inv.invoice_total ?? 0;
// The printed title only counts when the document holds a single record; in a multi-document PDF it describes just one of them.
const titleIsCredit = ctx.invoice_count === 1 && /\bcredit\s+(memo|note)\b/i.test(ctx.document_title || '');
if (titleIsCredit || ctx.document_type === 'CREDIT_MEMO' || (inv.invoice_total ?? 0) < 0 || total < 0) {
  ctx.lane = 'CREDIT_MEMO';
  return exc('CREDIT_MEMO_REVIEW', 'Credit memos are not auto-posted yet');
}

if (loc.status === 'CONFLICT') return exc('LOCATION_CONFLICT', `Location sources disagree: ${loc.method}`);
// A resolved location must exist and be live (both lanes).
if (loc.status === 'RESOLVED') {
  if (!loc.entity_id) return exc('LOCATION_NOT_IN_MASTER', `Location ${loc.code} has no Sage entity in Location_Master`);
  if (loc.active !== true) return exc('LOCATION_NOT_ACTIVE', `Location ${loc.code} (${loc.entity_id}) is not active yet in Location_Master`);
}

// PO invoices: Direct lane (location required)
if (ctx.po?.valid) {
  ctx.lane = 'DIRECT';
  if (loc.status !== 'RESOLVED') return exc('LOCATION_UNKNOWN', 'No location from PO suffix, ship-to or service address' + (loc.method ? ` (${loc.method})` : ''));
  if (!loc.st_tenant_id) return exc('LOCATION_NO_ST_TENANT', `Location ${loc.code} has no ServiceTitan tenant in Location_Master`);
  ctx.route = 'DIRECT';
  return [{ json: ctx }];
}

// Everything else is an indirect expense; Vendor_Account_Map decides GL, vendor and (if the document didn't) location.
const text = [ctx.vendor?.name, inv.charge_summary, ...(inv.line_items || []).map(l => l.description)].filter(Boolean).join(' ').toLowerCase();
const hit = list => { const r = list.find(re => re.test(text)); return r ? String(r) : null; };
const adv = hit(CONFIG.ADVERTISING), util = hit(CONFIG.UTILITY);
ctx.lane = adv ? 'INDIRECT_ADVERTISING' : (util ? 'INDIRECT_UTILITY' : 'INDIRECT_OTHER');
ctx.lane_evidence = adv || util || (inv.account_number ? `account ${inv.account_number}` : 'no PO');
ctx.route = 'INDIRECT';
return [{ json: ctx }];

// One item per PDF attachment. An email without a PDF becomes one item carrying its body text,
// so invoices sent in the email body (common for utilities) can be read like a PDF.
const htmlToText = h => String(h ?? '')
  .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d|table)>/gi, '\n')
  .replace(/<\/t[dh]>/gi, '\t')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&#39;|&apos;/gi, "'").replace(/&quot;/gi, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  // Works for both the Outlook trigger and the Gmail trigger (simple = off).
  const meta = {
    message_id: m.id ?? null,
    subject: m.subject ?? '',
    body_preview: m.bodyPreview ?? m.snippet ?? String(m.text ?? '').slice(0, 500),
    from: m.from?.emailAddress?.address ?? m.from?.value?.[0]?.address ?? m.from?.text ?? null,
    received_at: m.receivedDateTime ?? m.date ?? null,
  };
  let count = 0;
  for (const file of Object.values(item.binary ?? {})) {
    const name = String(file.fileName ?? '').trim();
    const mime = String(file.mimeType ?? '').trim().toLowerCase();
    if (!(mime === 'application/pdf' || name.toLowerCase().endsWith('.pdf'))) continue;
    count++;
    out.push({ json: { ...meta, file_name: name, has_pdf: true, source: 'PDF' }, binary: { data: file } });
  }
  if (!count) {
    const plain = String(m.text ?? '').trim();
    const body_text = plain.length > 40 ? plain : htmlToText(m.html ?? m.body?.content ?? m.textAsHtml ?? '');
    out.push({ json: { ...meta, file_name: null, has_pdf: false, source: 'EMAIL_BODY', body_text } });
  }
}
return out;

// If the sub-flow itself crashed, turn that into an exception that still carries the invoice context.
const r = $input.first()?.json;
if (!r || (r.error && !r.doc_id)) {
  const ctx = JSON.parse(JSON.stringify($('Classify Lane').first().json));
  ctx.status = 'SUBFLOW_ERROR';
  ctx.reason = `${ctx.lane} sub-flow failed: ${r?.error?.message || r?.error || 'no output'}`;
  return [{ json: ctx }];
}
return [{ json: r }];

const r = $input.first()?.json;
if (!r || (r.error && !r.doc_id)) {
  const ctx = JSON.parse(JSON.stringify($('Normalize Lane Result').first().json));
  ctx.status = 'POST_FAILED';
  ctx.reason = `Sage Post sub-flow failed: ${r?.error?.message || r?.error || 'no output'}`;
  return [{ json: ctx }];
}
return [{ json: r }];

// If the Statement sub-flow crashed, keep the document context and turn it into an exception.
const r = $input.first()?.json;
if (!r || (r.error && !r.doc_id)) {
  const ctx = JSON.parse(JSON.stringify($('Restore Routed Ctx').first().json));
  ctx.status = 'STATEMENT_FAILED';
  ctx.reason = `Statement sub-flow failed: ${r?.error?.message || r?.error || 'no output'}`;
  return [{ json: ctx }];
}
return [{ json: r }];

/*
 * Parse LLM output, normalize, validate, and split into one item per invoice.
 * Uses:
 *   - Extract from File: extracted PDF text and PDF metadata
 *   - Extract PDFs: Outlook email and attachment metadata
 *
 * Bad documents become EXCEPTION items instead of stopping the batch.
 */

const llmItems = $input.all();
const extractedItems = $('Prep Docs').all();   // text + source + __meta, aligned 1:1 with the LLM items
const TOL = $('Build Config').first().json.cfg.INV_PROC_CONFIG.validation_tolerance;


const out = [];

const errText = e =>
  typeof e === 'string' ? e : (e?.message || JSON.stringify(e));

const round2 = n => Math.round(n * 100) / 100;

/*
 * Strict amount parser.
 * Accepts JSON numbers and printed amounts: 1,234.56  -234.89  (234.89)  234.89-  $1,234.56
 * Anything else is REJECTED (bad = true), never "cleaned up". The old version stripped every
 * non-digit character, so a corrupted token such as "-234.!89!!89" silently became -234.8989.
 */
const AMOUNT_RE = /^(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?$|^\.\d+$/;

function parseAmount(v) {
  if (v === null || v === undefined || v === '') return { value: null, bad: false };
  if (typeof v === 'number') {
    return Number.isFinite(v) ? { value: v, bad: false } : { value: null, bad: true };
  }

  let s = String(v).trim();
  if (!s) return { value: null, bad: false };

  let neg = false;
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1).trim(); }
  if (/-$/.test(s)) { neg = true; s = s.slice(0, -1).trim(); }
  if (/^[-\u2212\u2013]/.test(s)) { neg = true; s = s.slice(1).trim(); }
  s = s.replace(/^[$\u20AC\u00A3]\s*/, '');

  if (!AMOUNT_RE.test(s)) return { value: null, bad: true };

  const n = Number(s.replace(/,/g, ''));
  if (!Number.isFinite(n)) return { value: null, bad: true };

  return { value: neg ? -n : n, bad: false };
}

const num = v => parseAmount(v).value;

/*
 * Every number printed in the document, as integer cents.
 * Used to prove that each amount the LLM returned really appears in the source text.
 */
function buildSrcCents(text) {
  const set = new Set();
  const add = s => { const n = Number(s); if (Number.isFinite(n)) set.add(Math.round(n * 100)); };
  for (const t of String(text).match(/\d[\d,]*(?:\.\d+)?|\.\d+/g) || []) {
    add(t.replace(/,/g, ''));
    // PDF text extraction can glue two numbers together (quantity 3 + price 149.99 -> 3149.99).
    // For a decimal token with no thousands separators and 4+ integer digits, also accept its trailing digit groups.
    const m = t.match(/^(\d{4,})(\.\d+)$/);
    if (m) for (let i = 1; i < m[1].length; i++) add(m[1].slice(i) + m[2]);
  }
  return set;
}

// Document types the prompt defines. Anything else is never processed as an invoice.
const ALLOWED_DOC_TYPES = ['INVOICE', 'CREDIT_MEMO', 'STATEMENT', 'MIXED', 'NOT_A_VALID_PDF'];
const ALLOWED_INVOICE_TYPES = ['INVOICE', 'CREDIT_MEMO'];
const normType = v => String(v ?? '').trim().toUpperCase().replace(/[\s-]+/g, '_');

// Statement amounts get the same checks as invoice amounts: readable, and present in the document text.
function checkStatementAmounts(st, srcCents) {
  const problems = [];
  const chk = (v, label) => {
    const r = parseAmount(v);
    if (r.bad) problems.push(`${label} unreadable "${String(v).slice(0, 40)}"`);
    else if (r.value !== null && r.value !== 0 && !srcCents.has(Math.round(Math.abs(r.value) * 100)))
      problems.push(`${label} ${r.value} not found in document text`);
  };
  for (const k of ['previous_balance', 'payments', 'credits', 'current_charges', 'amount_due']) chk(st?.[k], k);
  (Array.isArray(st?.transactions) ? st.transactions : []).forEach((t, i) => {
    chk(t?.amount, `transaction ${i + 1} amount`);
    chk(t?.balance, `transaction ${i + 1} balance`);
  });
  return problems;
}

const MONEY_KEYS = [
  'subtotal', 'freight', 'tax', 'invoice_total',
  'amount_due', 'current_charges', 'previous_balance'
];

function normalizeStatement(st, warnings) {
  if (!st || typeof st !== 'object') return st ?? null;
  const o = { ...st };
  const fix = (obj, k, label) => {
    if (!(k in obj)) return;
    const r = parseAmount(obj[k]);
    if (r.bad) warnings.push(`Unreadable statement ${label} "${String(obj[k]).slice(0, 40)}"`);
    obj[k] = r.value;
  };
  for (const k of ['previous_balance', 'payments', 'credits', 'current_charges', 'amount_due']) fix(o, k, k);
  if (Array.isArray(o.transactions)) {
    o.transactions = o.transactions.map((t, i) => {
      const x = { ...(t || {}) };
      fix(x, 'amount', `transaction ${i + 1} amount`);
      fix(x, 'balance', `transaction ${i + 1} balance`);
      return x;
    });
  }
  return o;
}

const pad = x => String(x).padStart(2, '0');

function isoDate(v) {
  if (!v) return null;

  const s = String(v).trim();

  // YYYY-MM-DD or YYYY-MM-DD followed by a time
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

  if (m) {
    return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  }

  // MM/DD/YYYY, MM-DD-YYYY, or MM.DD.YYYY
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);

  if (m) {
    const year = m[3].length === 2 ? '20' + m[3] : m[3];
    return `${year}-${pad(m[1])}-${pad(m[2])}`;
  }

  const d = new Date(s);

  if (!isNaN(d.getTime())) {
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }

  return null;
}

function parseLLM(resp) {
  if (!resp || resp.error) {
    return {
      error: 'LLM request failed' +
        (resp?.error ? `: ${errText(resp.error)}` : '')
    };
  }

  const choice = resp.choices?.[0];
  const raw = choice?.message?.content;

  const finish = choice?.finish_reason;
  if (finish === 'length') {
    return { error: 'LLM output truncated (finish_reason=length); raise glm_header_max_tokens' };
  }
  if (finish !== undefined && finish !== null && finish !== 'stop') {
    return { error: `LLM did not finish normally (finish_reason=${finish})` };
  }

  if (!raw) {
    return { error: 'LLM returned empty content' };
  }

  const cleaned = String(raw)
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .trim();

  try {
    return { data: JSON.parse(cleaned) };
  } catch (e) {
    const a = cleaned.indexOf('{');
    const b = cleaned.lastIndexOf('}');

    if (a >= 0 && b > a) {
      try {
        return { data: JSON.parse(cleaned.slice(a, b + 1)) };
      } catch (e2) {
        // Continue to the parsing error below.
      }
    }

    const at = Number((/position (\d+)/.exec(e.message) || [])[1]);
    const near = Number.isFinite(at)
      ? ' near: ' + JSON.stringify(cleaned.slice(Math.max(0, at - 30), at + 30))
      : '';

    return {
      error: 'Could not parse LLM JSON: ' + e.message + near
    };
  }
}

const pick = (o, keys) =>
  Object.fromEntries(keys.map(k => [k, o?.[k] ?? null]));

/*
 * Normalize one invoice or credit memo.
 */
function buildInvoice(shared, inv, k, count, parentDocType, srcCents) {
  const warnings = [];

  // Strict amounts: unreadable or not-in-document values fail this invoice instead of flowing on.
  const m = {};
  const integrity = [];

  for (const key of MONEY_KEYS) {
    const r = parseAmount(inv[key]);
    m[key] = r.value;

    if (r.bad) {
      integrity.push(`${key} unreadable "${String(inv[key]).slice(0, 40)}"`);
    } else if (
      r.value !== null &&
      r.value !== 0 &&
      !srcCents.has(Math.round(Math.abs(r.value) * 100))
    ) {
      integrity.push(`${key} ${r.value} not found in document text`);
    }
  }

  const individualDocType = normType(
    inv.document_type ||
    (String(inv.invoice_category || '').toUpperCase() === 'CREDIT_MEMO'
      ? 'CREDIT_MEMO'
      : parentDocType === 'MIXED'
        ? 'INVOICE'
        : parentDocType || 'INVOICE')
  );

  const lines = (Array.isArray(inv.line_items) ? inv.line_items : [])
    .map(li => ({
      sku: li.sku ?? null,
      description: li.description ?? null,
      quantity: num(li.quantity),
      unit_price: num(li.unit_price),
      amount: num(li.amount)
    }))
    .filter(l => l.sku || l.description || l.amount !== null);

  const invoice = {
    invoice_number: inv.invoice_number
      ? String(inv.invoice_number).trim()
      : null,

    invoice_date: isoDate(inv.invoice_date),
    invoice_date_raw: inv.invoice_date ?? null,

    due_date: isoDate(inv.due_date),
    due_date_raw: inv.due_date ?? null,

    payment_terms: inv.payment_terms ?? inv.term ?? null,

    po_number_raw: inv.po_number
      ? String(inv.po_number).trim()
      : null,

    account_number: inv.account_number
      ? String(inv.account_number).trim()
      : null,

    job_number: inv.job_number ?? null,
    service_address: inv.service_address ?? null,
    charge_summary: inv.charge_summary ?? null,

    subtotal: m.subtotal,
    freight: m.freight,
    tax: m.tax,
    invoice_total: m.invoice_total,
    amount_due: m.amount_due,
    current_charges: m.current_charges,
    previous_balance: m.previous_balance,

    line_items: lines
  };

  if (inv.due_date && !invoice.due_date) {
    warnings.push(`Unreadable due date "${inv.due_date}"`);
  }

  /*
   * Use printed totals when present.
   * Derive totals only when they are missing.
   */
  const priced = lines.filter(l => l.amount !== null);
  const lineSum = round2(
    priced.reduce((sum, l) => sum + l.amount, 0)
  );

  if (invoice.subtotal === null && priced.length) {
    invoice.subtotal = lineSum;
    warnings.push('Subtotal derived from line items');
  }

  if (invoice.invoice_total === null) {
    if (invoice.amount_due !== null) {
      invoice.invoice_total = invoice.amount_due;
      warnings.push('Invoice total taken from amount due');
    } else if (invoice.subtotal !== null) {
      invoice.invoice_total = round2(
        invoice.subtotal +
        (invoice.tax ?? 0) +
        (invoice.freight ?? 0)
      );

      warnings.push(
        'Invoice total derived from subtotal + tax + freight'
      );
    }
  }

  // Arithmetic checks: warnings only.
  for (const line of lines) {
    if (
      line.quantity !== null &&
      line.unit_price !== null &&
      line.amount !== null &&
      Math.abs(
        round2(line.quantity * line.unit_price) - line.amount
      ) > TOL
    ) {
      warnings.push(
        `Line ${line.sku ?? line.description}: qty × price ≠ amount`
      );
    }
  }

  if (
    priced.length &&
    invoice.subtotal !== null &&
    Math.abs(lineSum - invoice.subtotal) > TOL &&
    Math.abs(
      lineSum + (invoice.freight ?? 0) - invoice.subtotal
    ) > TOL
  ) {
    warnings.push(
      `Line items sum ${lineSum} ≠ subtotal ${invoice.subtotal}`
    );
  }

  if (
    invoice.subtotal !== null &&
    invoice.invoice_total !== null
  ) {
    const expected = round2(
      invoice.subtotal +
      (invoice.tax ?? 0) +
      (invoice.freight ?? 0)
    );

    const subtotalPlusTax = round2(
      invoice.subtotal + (invoice.tax ?? 0)
    );

    if (
      Math.abs(expected - invoice.invoice_total) > TOL &&
      Math.abs(subtotalPlusTax - invoice.invoice_total) > TOL
    ) {
      warnings.push(
        `Subtotal + tax + freight (${expected}) ≠ total ${invoice.invoice_total}`
      );
    }
  }

  // Utility bills sometimes have no printed invoice number.
  if (
    !invoice.invoice_number &&
    invoice.account_number &&
    invoice.invoice_date
  ) {
    invoice.invoice_number =
      `${invoice.account_number.replace(/[^A-Za-z0-9]/g, '')}-` +
      `${invoice.invoice_date.replace(/-/g, '')}`;

    warnings.push(
      `No invoice number printed; using ${invoice.invoice_number}`
    );
  }

  // Printed totals must add up. A digit-level corruption almost always breaks this sum.
  // Invoices with deposits, discounts or partial payments printed between subtotal and total can fail here legitimately; they go to review instead of posting.
  const printedTotal = m.invoice_total ?? m.amount_due;
  const totalsBad = m.subtotal !== null && printedTotal !== null &&
    Math.abs(round2(m.subtotal + (m.tax ?? 0) + (m.freight ?? 0)) - printedTotal) > TOL &&
    Math.abs(round2(m.subtotal + (m.tax ?? 0)) - printedTotal) > TOL;

  const missing = [];

  // No printed vendor name is OK on a PO invoice: the Direct flow takes the vendor from the ServiceTitan PO.
  if (!shared.vendor?.name) {
    if (invoice.po_number_raw) warnings.push('Vendor name not printed; will use the ServiceTitan PO vendor');
    else missing.push('vendor name');
  }
  if (!invoice.invoice_number) missing.push('invoice number');
  if (!invoice.invoice_date) missing.push('invoice date');
  if (invoice.invoice_total === null) missing.push('invoice total');

  /*
   * Keep document_type and invoice_category at the top level
   * so downstream routing can distinguish credit memos.
   */
  let invoiceCategory = inv.invoice_category ?? null;

  if (
    individualDocType === 'CREDIT_MEMO' &&
    !invoiceCategory
  ) {
    invoiceCategory = 'CREDIT_MEMO';
  }

  const ctx = {
    ...shared,

    doc_id: `${shared.doc_id}-${k + 1}`,
    invoice_index: k + 1,
    invoice_count: count,

    document_type: individualDocType,
    invoice_category: invoiceCategory,

    invoice,

    warnings: [...(shared.warnings || []), ...warnings],

    route: null,
    status: null,
    reason: null
  };

  if (!ALLOWED_INVOICE_TYPES.includes(individualDocType)) {
    ctx.route = 'EXCEPTION';
    ctx.status = 'UNSUPPORTED_DOCUMENT_TYPE';
    ctx.reason = `Unsupported document_type "${individualDocType || 'none'}" on an invoice record`;
